function renderCallPresence(){
 const target=$('#conversation-call-presence');if(!target)return;
 const call=active()?.call,participants=call?.participants||[],local=!!call&&engine?.info?.id===call.id,joined=local&&participants.some(p=>p.uid===S.user.uid);
 target.hidden=!participants.length;if(!participants.length){target.innerHTML='';target.dataset.signature='';return;}
 const signature=JSON.stringify([call.id,participants.map(p=>p.uid),local,joined]);if(target.dataset.signature===signature)return;target.dataset.signature=signature;
 target.innerHTML=`<div class="call-presence-avatars">${participants.map(p=>`<span title="${e(user(p.uid).name)}">${avatar(user(p.uid),'small')}</span>`).join('')}</div><div class="call-presence-copy"><strong>${joined?'You are in this call':local?'Joining call…':'Call in progress'}</strong><span>In call: ${e(callNames(call))}</span></div>${local?'':'<button class="success-button call-presence-join" data-action="join-existing-call">Join Call</button>'}`;
}
function syncIncoming(){
 const incoming=S.conversations.map(c=>c.call).filter(Boolean).find(c=>c.status==='ringing'&&serverNow()<c.created+30000&&c.caller!==S.user.uid&&c.participants?.some(p=>p.uid===c.caller)&&!c.participants.some(p=>p.uid===S.user.uid)&&engine?.info?.id!==c.id&&!sessionStorage.getItem('pixl.dismiss.'+c.id));
 if(incoming)showIncoming(incoming);else hideIncoming();
}
function applyCallPresence(data){
 const conversation=S.conversations.find(c=>c.id===data.conversation);if(!conversation)return;
 const prior=callEvents.get(data.conversation);if(prior?.id===data.id&&prior.revision>data.revision)return;
 if(conversation.call&&conversation.call.id!==data.id&&(!data.call||conversation.call.created>data.call.created))return;
 callEvents.set(data.conversation,{id:data.id,revision:data.revision||0,call:data.call,receivedAt:Date.now()});conversation.call=data.call;
 if(data.call?.status==='active'&&engine?.info?.id===data.id)engine.info.status='active';
 renderSidebar();if(S.view==='chat'){renderHeader();renderCallPresence();}else if(S.view==='friends'&&S.tab!=='add')renderContent();syncIncoming();updateCall();
}
