async function sendDrawing(file,{uid,conversation:cid,sourceId,id,onProgress}){
 if(S.user?.uid!==uid)throw Error('Your account changed. Reopen your sketchbook to send this drawing.');
 const result=await uploadWithProgress(file,onProgress);
 if(S.user?.uid!==uid)throw Error('Your account changed. Your drawing remains saved in your sketchbook.');
 await hydrateFiles([{attachment:result.upload}]);
 if(S.user?.uid!==uid)throw Error('Your account changed. Your drawing remains saved in your sketchbook.');
 const message={id,conversation:cid,sender:uid,text:sourceId?'A new version of your sketch':'',upload:result.upload.id,attachment:result.upload,...(sourceId?{reply_to:sourceId}:{}),created:Date.now(),pending:true};
 S.outbox.push(message);persistOutbox();if(S.active===cid&&S.view==='chat')renderMessages();
 await flushOutbox();return {queued:S.outbox.some(m=>m.id===id)};
}
