 try{const data=await api('/me');S.user=data.user;if(!S.user){const saved=JSON.parse(sessionStorage.getItem('pixl.signup')||'{}');S.user=(await api('/me',{method:'PUT',body:{name:saved.name||auth.currentUser.email.split('@')[0],handle:saved.handle||auth.currentUser.email.split('@')[0]}})).user;}rememberAccount(S.user).catch(()=>{});prefs();S.outbox=readStored('pixl.outbox.'+S.user.uid,[]);shell();showOpeningTheme();engine=new CallEngine({api,user:S.user,settings:S.prefs});engine.addEventListener('change',updateCall);engine.addEventListener('speaking',()=>updateSpeaking($('#call-stage'),engine));engine.addEventListener('stats',()=>{if($('#diagnostics-content'))renderDiagnostics();});engine.addEventListener('error',ev=>toast(ev.detail));engine.addEventListener('soundboard',ev=>{sound(ev.detail.sound);toast(user(ev.detail.uid).name+' played a sound.')});await api('/session',{method:'POST'});await refresh();await connections.load();connectLive();refreshTimer=setInterval(()=>refresh().catch(()=>{}),30000);flushOutbox();}catch(error){root.innerHTML=`<main class="auth-screen"><div class="auth-card"><h1>Connection interrupted</h1><p>${e(error.message)}</p><button class="primary" data-action="reload">Try again</button></div></main>`;}
