 for(let offset=0;offset<ids.length;offset+=100)setExpressionLinks((await api('/expression-links',{method:'POST',body:{ids:ids.slice(offset,offset+100)}})).links);
 for(const m of messages)if(m.attachment?.expressionId)m.attachment.url=expressionURL(m.attachment.expressionId)||m.attachment.url;
 const attachments=messages.flatMap(m=>m.attachment?.kind==='files'?m.attachment.files:[m.attachment]).filter(a=>a&&!a.kind&&!a.url);if(!attachments.length)return;
 for(let offset=0;offset<attachments.length;offset+=50){const batch=attachments.slice(offset,offset+50),data=await api('/file-links',{method:'POST',body:{ids:batch.map(a=>a.id)}});for(const a of batch)a.url=data.links[a.id];}
