const outboxPump=createOutboxPump({state:()=>S,send:m=>api('/conversations/'+encodeURIComponent(m.conversation)+(m.command?'/commands':'/messages'),{method:'POST',signal:AbortSignal.timeout(15000),body:m.command?{id:m.id,command:m.command,args:m.commandArgs||''}:{id:m.id,text:m.text,upload:m.upload,uploads:m.uploads,asset:m.asset,gif:m.gif,replyTo:m.reply_to}}),accept:acceptedMessage,changed:()=>{persistOutbox();renderMessages();}});
const flushOutbox=()=>outboxPump.flush();

// Live music cards use Vela's existing message update/broadcast endpoint.
// No new Worker route is required: the original message ID is updated in place.
const liveMusicStore=()=>S.user?'vela.music.live-messages.'+S.user.uid:'';
function liveMusicRecords(){
 try{
  const records=JSON.parse(localStorage.getItem(liveMusicStore())||'[]');
  return Array.isArray(records)?records.filter(x=>x&&/^[\da-f-]{36}$/i.test(x.id)&&typeof x.conversation==='string'&&Date.now()-Number(x.created)<86400000).slice(-3):[];
 }catch{return []}
}
function saveLiveMusicRecords(records){if(S.user)localStorage.setItem(liveMusicStore(),JSON.stringify(records.slice(-3)));}
let liveMusicUpdating=false,liveMusicLastUpdate=0,liveMusicLastSignature='',liveMusicSyncPending=false;
async function synchronizeLiveMusic(track,force=false){
 if(!S.user||!track?.title)return false;
 const records=liveMusicRecords();if(!records.length)return false;
 const signature=[track.title,track.artist,track.playing,track.duration].join('\0');
 if(liveMusicUpdating){if(force||signature!==liveMusicLastSignature)liveMusicSyncPending=true;return false}
 if(!force&&signature===liveMusicLastSignature&&Date.now()-liveMusicLastUpdate<12000)return true;
 liveMusicUpdating=true;
 try{
  const token=createLiveMusicMessage(track),kept=[];
  for(const item of records){
   try{await api('/messages/'+encodeURIComponent(item.id),{method:'PATCH',body:{text:token}});kept.push(item);}
   catch(error){
    if(!/\b(403|404)\b/.test(String(error.message||'')))kept.push(item);
   }
  }
  saveLiveMusicRecords(kept);
  liveMusicLastSignature=signature;liveMusicLastUpdate=Date.now();
  return kept.length>0;
 }finally{
  liveMusicUpdating=false;
  if(liveMusicSyncPending){liveMusicSyncPending=false;setTimeout(()=>synchronizeLiveMusic(track,true).catch(()=>{}),0);}
 }
}
window.velaMusic={
 api:(path,options)=>api(path,options),
 selfUid:()=>S.user?.uid||null,
 conversationPeer:()=>{const c=active();return S.view==='chat'&&c?.kind!=='group'?other(c)?.uid||null:null;},
 publishLocal:music=>{if(S.user?.uid)refreshOwnLiveMusic(S.user.uid,music);},
 syncLive:track=>synchronizeLiveMusic(track).catch(()=>false),
 sendLive:async track=>{
  const c=active();
  if(!S.user||S.view!=='chat'||!c)throw Error('Open a conversation to send your live music.');
  const text=createLiveMusicMessage(track);
  const message={id:crypto.randomUUID(),conversation:c.id,sender:S.user.uid,text,created:Date.now(),pending:true};
  S.outbox.push(message);persistOutbox();renderMessages();
  const scroll=$('#message-scroll');if(scroll)scroll.scrollTop=scroll.scrollHeight;
  await flushOutbox();
  const records=liveMusicRecords();
  records.push({id:message.id,conversation:c.id,created:Date.now()});
  saveLiveMusicRecords(records);
  liveMusicLastUpdate=Date.now();liveMusicLastSignature=[track.title,track.artist,track.playing,track.duration].join('\0');
  return true;
 }
};

function sendExpression(media,preview,cid){
 if(!cid||!S.user)return;
 const attachment={kind:preview.kind,name:preview.name,type:preview.type||'image/gif',size:preview.size,url:preview.url,...(media.asset?{expressionId:media.asset}:{})};
 S.outbox.push({id:crypto.randomUUID(),conversation:cid,sender:S.user.uid,text:'',...media,attachment,created:Date.now(),pending:true});persistOutbox();renderMessages();flushOutbox();
}
function scheduleMessage(){const input=$('#composer'),text=input?.value.trim();if(!text)return toast('Write a message before scheduling it.');const minimum=new Date(Date.now()+60000),local=new Date(minimum.getTime()-minimum.getTimezoneOffset()*60000).toISOString().slice(0,16);const dialog=modal('Schedule message',`<p class="schedule-preview">${messageHTML(text)}</p><label>SEND DATE AND TIME<input id="schedule-time" type="datetime-local" min="${local}" value="${local}"></label><p class="muted">Vela will send this from the server even when your devices are offline.</p><footer><button class="text-button" data-cancel>Cancel</button><button class="primary" data-confirm-schedule>Schedule message</button></footer>`);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm-schedule]').onclick=()=>act(async()=>{const deliverAt=new Date(dialog.querySelector('#schedule-time').value).getTime();await api('/scheduled-messages',{method:'POST',body:{id:crypto.randomUUID(),conversation:S.active,text,replyTo:S.reply?.id,deliverAt}});input.value='';input.style.height='auto';localStorage.removeItem('pixl.draft.'+S.user.uid+'.'+S.active);S.reply=null;renderReply();dialog.close();toast('Message scheduled for '+new Date(deliverAt).toLocaleString()+'.');});}
async function scheduledMessages(){const {items}=await api('/scheduled-messages');const dialog=modal('Scheduled messages',items.length?`<div class="scheduled-list">${items.map(item=>`<article><div><strong>${e(title(S.conversations.find(c=>c.id===item.conversation)))}</strong><p>${messageHTML(item.text)}</p><time>${e(new Date(item.deliver_at).toLocaleString())}</time></div><button class="icon-button" data-cancel-scheduled="${e(item.id)}" aria-label="Cancel scheduled message">${icon('trash')}</button></article>`).join('')}</div>`:empty('schedule','Nothing scheduled','Use the clock beside Send to choose a delivery time.'));dialog.querySelectorAll('[data-cancel-scheduled]').forEach(button=>button.onclick=()=>act(async()=>{await api('/scheduled-messages/'+encodeURIComponent(button.dataset.cancelScheduled),{method:'DELETE'});button.closest('article').remove();toast('Scheduled message canceled.');}));}
async function takeChatPhoto(){const cid=S.active;if(!cid)return;await capturePhoto({modal,stream:engine?.camera,settings:S.prefs,onDeviceChange:()=>savePrefs(),onSend:async file=>{const result=await api('/uploads',{method:'POST',headers:{'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)},body:file});await hydrateFiles([{attachment:result.upload}]);const message={id:crypto.randomUUID(),conversation:cid,sender:S.user.uid,text:'',upload:result.upload.id,attachment:result.upload,created:Date.now(),pending:true};S.outbox.push(message);persistOutbox();if(S.active===cid)renderMessages();await flushOutbox();if(S.outbox.some(m=>m.id===message.id))toast('Photo queued. It will retry when the connection returns.')}})}
async function uploadFile(file){
 if(file.size>95*1024*1024)return toast('Files can be up to 95 MB.');
 if(!S.active||!S.user)return;
 const cid=S.active,uid=S.user.uid,request=++uploadRequest;
 uploading=true;uploadName=file.name;uploadPercent=0;uploadFailure=null;renderUpload();
 const current=()=>request===uploadRequest&&S.user?.uid===uid&&cid===S.active&&S.view==='chat';
 try{
  const result=await uploadWithProgress(file,percent=>{if(current()){uploadPercent=percent;renderUpload();}});
  if(!current())return;
  await hydrateFiles([{attachment:result.upload}]);
  if(!current())return;
  S.upload=result.upload;
 }catch(err){if(current()){uploadFailure=file;toast(err.message);}}
 finally{if(request===uploadRequest){uploading=false;uploadName='';renderUpload();}}
}
async function uploadWithProgress(file,onProgress=()=>{}){const cid=active()?.id||engine?.info?.conversation;if(!cid)throw Error('Open a conversation first.');return connections.queue.add(file,cid,{onProgress});}
async function uploadFiles(files){if(files.length>10)return toast('Choose up to 10 files.');if(!S.active||!S.user)return;const cid=S.active,uid=S.user.uid,request=++uploadRequest;uploading=true;uploadName=files.length+' files';uploadPercent=0;renderUpload();const results=[];try{for(const [index,file]of files.entries()){const {upload}=await connections.queue.add(file,cid,{onProgress:p=>{if(request===uploadRequest){uploadPercent=Math.round((index+p/100)/files.length*100);renderUpload();}}});results.push(upload);}if(S.active===cid&&S.user?.uid===uid&&request===uploadRequest){S.upload=results.length===1?results[0]:{kind:'files',files:results,name:results.length+' files',type:'application/octet-stream',size:results.reduce((n,f)=>n+f.size,0)};await hydrateFiles([{attachment:S.upload}]);}}catch(error){toast(error.message)}finally{if(request===uploadRequest){uploading=false;renderUpload();}}}

function renderUpload(){
 const preview=$('#upload-preview');
 if(preview)preview.innerHTML=uploading?`<div class="upload-progress" role="status">Uploading ${e(uploadName)} · ${uploadPercent}%<progress value="${uploadPercent}" max="100" aria-label="Upload progress"></progress></div>`:uploadFailure?`<div class="upload-progress">${e(uploadFailure.name)} · Upload failed <button type="button" data-action="retry-upload">Retry</button></div>`:S.upload?`<div class="upload-progress">${S.upload.type.startsWith('image/')&&S.upload.url?`<img class="upload-thumbnail" src="${e(S.upload.url)}" alt="Attachment preview">`:icon('file')}<span>${e(S.upload.name)} · ${bytes(S.upload.size)}</span>${button('close','Remove Attachment','remove-upload')}</div>`:'';
 const send=$('#composer-form .send-button');if(send)send.disabled=uploading;
}
function renderReply(){if($('#reply-preview'))$('#reply-preview').innerHTML=S.reply?`<div class="reply-preview">Replying to <strong>${e(user(S.reply.sender).name)}</strong><span>${e(S.reply.text.slice(0,100))}</span>${button('close','Cancel Reply','cancel-reply')}</div>`:'';}
  function updateDock(){if(!$('#account-dock')||!S.user)return;stableCallMarkup($('#account-dock'),`<button class="self-profile" data-action="self-profile" aria-label="Manage profile and status" aria-haspopup="dialog" aria-expanded="${!!accountCard}">${avatar(S.user)}<span><strong>${e(S.user.name)}</strong><small>${e(S.user.handle)}</small></span></button><div class="dock-controls"><div class="dock-split">${button(S.prefs.muted?'micOff':'mic',S.prefs.muted?'Unmute':'Mute','mute',S.prefs.muted?'muted-control':'')}${button('down','Input Options','input-options','device-chevron')}</div><div class="dock-split">${button(engine?.deafened?'deaf':'headphones',engine?.deafened?'Undeafen':'Deafen','deafen')}${button('down','Output Options','output-options','device-chevron')}</div>${button('settings','User Settings','settings')}</div>`);}
async function connectLive(){clearTimeout(liveRetry);if(!S.user||!navigator.onLine)return connectionStatus();const generation=++liveGeneration,prior=live;if(prior){prior.onclose=null;prior.close()}try{const uid=S.user.uid,{ticket}=await api('/ticket',{method:'POST',body:{scope:'live'}});if(S.user?.uid!==uid||generation!==liveGeneration)return;const socket=live=new WebSocket(socketURL('/live',ticket));socket.onopen=()=>{if(generation!==liveGeneration)return socket.close();liveFailures=0;S.live=true;connectionStatus();refresh().catch(()=>{});};socket.onmessage=ev=>{if(generation!==liveGeneration||!S.user||ev.data==='pong')return;let data;try{data=JSON.parse(ev.data)}catch{return}if(data.type==='typing'&&data.uid!==S.user.uid&&data.conversation===S.active){$('#typing-label').textContent=data.typing?user(data.uid).name+' is typing…':'';clearTimeout(typingTimer);typingTimer=setTimeout(()=>{if($('#typing-label'))$('#typing-label').textContent='';},4500);}if(data.type==='call-presence'){applyCallPresence(data);return;}if(data.type==='movie-state')act(()=>movies.receive(data,data.conversation));if(['message','message-updated'].includes(data.type)){if(data.conversation===S.active){if(data.type==='message')acceptLiveMessage(data).catch(()=>loadMessages());else loadMessages();if(document.visibilityState==='visible')api('/conversations/'+encodeURIComponent(S.active)+'/read',{method:'POST'}).catch(()=>{});}if(data.type==='message'&&data.sender!==S.user.uid&&S.user.status!=='dnd'&&!connections.isMuted(data.conversation)){sound('message1');connections.notify(data);}refresh();}if(['refresh','read','call','call-ended','call-updated'].includes(data.type)){refresh();if(data.type==='call-ended'&&engine?.info?.id===data.id&&(!data.legacyOnly||!engine.device)){const joinedEngine=engine,device=engine.device;api('/calls/'+data.id).then(result=>{if(!result.call&&engine===joinedEngine&&engine.device===device&&engine.info?.id===data.id)engine.leave();}).catch(()=>{});}}};socket.onclose=()=>{if(generation!==liveGeneration)return;S.live=false;if(!S.user)return;const delay=Math.min(12000,1000*2**Math.min(liveFailures++,4));connectionStatus();liveRetry=setTimeout(()=>api('/session',{method:'POST'}).then(connectLive).catch(()=>{liveRetry=setTimeout(connectLive,delay)}),delay);};socket.onerror=()=>socket.close();}catch{if(S.user&&generation===liveGeneration){S.live=false;liveFailures++;connectionStatus();liveRetry=setTimeout(connectLive,Math.min(12000,1000*2**Math.min(liveFailures,4)));}}}
setInterval(()=>{if(live?.readyState===1)live.send('ping');},30000);
function connectionStatus(){const el=$('#connection-banner');if(!el)return;const offline=!navigator.onLine,retrying=!offline&&liveFailures>0&&live?.readyState!==1;el.hidden=!offline&&!retrying;el.textContent=offline?'You’re offline. Messages will send when you reconnect.':'Reconnecting to live updates…';}
function modal(title,html,{wide=false,onclose}={}){closeMenu();const dialog=document.createElement('dialog');dialog.setAttribute('aria-label',title);dialog.className='modal '+(wide?'wide-modal':'');dialog.innerHTML=`<header><h2>${e(title)}</h2><button class="icon-button" aria-label="Close">${icon('close')}</button></header><div class="modal-content">${html}</div>`;layers.append(dialog);dialog.querySelector('header button').onclick=()=>dialog.close();dialog.addEventListener('click',ev=>{if(ev.target===dialog){const r=dialog.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{onclose?.();dialog.remove();});dialog.showModal();return dialog;}
let menu,accountCard;

let expressionRequest=0;
function closeMenu(){expressionRequest++;menu?.dispose?.();menu?.remove();menu=null;accountCard?.remove();accountCard=null;}
function popup(anchor,items){closeMenu();menu=document.createElement('div');menu.className='popover-menu';menu.setAttribute('role','menu');menu.innerHTML=items.map(item=>item==='-'?'<hr>':`<button role="${typeof item.checked==='boolean'?'menuitemcheckbox':'menuitem'}" ${typeof item.checked==='boolean'?'aria-checked="'+item.checked+'"':''} ${item.disabled?'disabled':''} data-menu="${e(item.id)}" class="${item.danger?'danger':''}">${item.icon?icon(item.icon,18):''}<span>${e(item.label)}</span>${typeof item.checked==='boolean'?'<i class="menu-checkbox '+(item.checked?'checked':'')+'">'+(item.checked?icon('check',14):'')+'</i>':''}</button>`).join('');layers.append(menu);const r=anchor.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(innerWidth-menu.offsetWidth-8,r.right-menu.offsetWidth))+'px';menu.style.top=Math.max(8,Math.min(innerHeight-menu.offsetHeight-8,r.bottom+6))+'px';menu.querySelectorAll('button').forEach(b=>b.onclick=()=>{const item=items.find(i=>i.id===b.dataset.menu);closeMenu();act(()=>item.run?.());});menu.querySelector('button:not(:disabled)')?.focus();menu.onkeydown=ev=>{const buttons=[...menu.querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement);if(ev.key==='ArrowDown'){ev.preventDefault();buttons[(i+1)%buttons.length].focus();}if(ev.key==='ArrowUp'){ev.preventDefault();buttons[(i-1+buttons.length)%buttons.length].focus();}};}
document.addEventListener('pointerdown',ev=>{if(menu&&!menu.contains(ev.target))closeMenu();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeMenu();if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){if(!S.user||document.querySelector('dialog[open]'))return;ev.preventDefault();quickSearch();}});
function legacyQuickSearch(){const dialog=modal('Find a conversation',`<div class="modal-search">${icon('search')}<input id="quick-query" placeholder="Search people or groups" autofocus aria-label="Search people or groups"></div><div id="quick-results"></div>`);const draw=()=>{const q=dialog.querySelector('input').value.toLowerCase();const cs=S.conversations.filter(c=>title(c).toLowerCase().includes(q));dialog.querySelector('#quick-results').innerHTML=cs.map(c=>`<button class="search-result" data-result="${e(c.id)}">${c.kind==='group'?icon('users'):avatar(other(c))}<span>${e(title(c))}</span>${icon('arrow',16)}</button>`).join('')||'<p class="muted">No conversations found.</p>';dialog.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{dialog.close();openChat(b.dataset.result);});};dialog.querySelector('input').oninput=draw;draw();}
function quickSearch(){connections.search();}
function newGroup(){const friends=S.friends.filter(f=>f.status==='accepted');const dialog=modal('New Message',`<p>Group messages can have up to 20 members.</p><input class="full-input" id="group-name" maxlength="60" placeholder="Group name (optional)"><div class="member-picker">${friends.map(f=>`<label>${avatar(f)}<span>${e(f.name)}<small>${e(f.handle)}</small></span><input type="checkbox" value="${e(f.uid)}"></label>`).join('')||'<p>Add a friend first.</p>'}</div><footer><button class="text-button" data-cancel>Cancel</button><button class="primary" data-create disabled>Create Message</button></footer>`);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onchange=()=>{dialog.querySelector('[data-create]').disabled=!dialog.querySelector('input[type=checkbox]:checked')};dialog.querySelector('[data-create]').onclick=()=>act(async()=>{const selected=[...dialog.querySelectorAll('input:checked')].map(el=>el.value);const result=await api('/conversations',{method:'POST',body:{members:selected,name:dialog.querySelector('#group-name').value,group:selected.length>1}});dialog.close();await refresh();await openChat(result.id);});}
function openAccountPopover(){if(accountCard){closeMenu();return}closeMenu();const anchor=$('#account-dock');accountCard=accountPopover({anchor,profile:S.user,accounts:savedAccounts(S.user),edit:()=>profile(S.user.uid),setStatus:async status=>{S.user=(await api('/me',{method:'PUT',body:{status}})).user;rememberAccount(S.user).catch(()=>{});updateDock();},manage:manageAccounts,switchAccount:uid=>act(()=>activateAccount(uid)),copy:async(value,message)=>{try{if(value!==null)await navigator.clipboard.writeText(value);toast(message)}catch{toast('Clipboard access was denied.')}},onclose:()=>{accountCard=null;$('.self-profile')?.setAttribute('aria-expanded','false')}});$('.self-profile').setAttribute('aria-expanded','true');const element=accountCard.element;profiles.get(S.user.uid).then(p=>{if(!element.isConnected)return;element.querySelector('.account-popover-banner').style.background=p.banner;const info=document.createElement('div');info.className='account-profile-extra';info.innerHTML=(p.pronouns?'<p>'+e(p.pronouns)+'</p>':'')+(p.bio?'<div class="profile-bio">'+messageHTML(p.bio)+'</div>':'')+profiles.compact(p);element.querySelector('.account-popover-identity').append(info);info.querySelector('.profile-game-collection').onclick=()=>{closeMenu();profiles.full(p)};element.style.top=Math.max(8,$('#account-dock').getBoundingClientRect().top-element.offsetHeight-8)+'px';renderEmoji(info)}).catch(()=>{});}
async function activateAccount(uid){if(uid===S.user.uid)return;await movies.close();await engine?.leave();clearInterval(refreshTimer);clearTimeout(liveRetry);if(live){live.onclose=null;live.close();live=null}closeMenu();S.active=null;S.messages=[];S.view='friends';S.tab='online';layers.querySelectorAll('dialog').forEach(d=>d.close());await switchAccount(uid);}
function manageAccounts(){const accounts=savedAccounts(S.user);const dialog=modal('Manage Accounts',`<p class="manage-accounts-intro">Switch accounts, sign in, sign out.</p><div class="managed-accounts">${accounts.map(a=>`<div class="managed-account">${avatar({...a,last_seen:Date.now()})}<span><strong>${e(a.name)}</strong><small>${e(a.handle)}</small></span>${a.uid===S.user.uid?'<span class="current-account">'+icon('check',18)+'</span>':'<button class="secondary" data-switch-account="'+e(a.uid)+'">Switch</button>'}<button class="icon-button" data-account-options="${e(a.uid)}" aria-label="More options for ${e(a.handle)}">${icon('more')}</button></div>`).join('')}</div><button class="secondary wide" data-add-account>Add an account</button>`);dialog.querySelectorAll('[data-switch-account]').forEach(b=>b.onclick=()=>act(()=>activateAccount(b.dataset.switchAccount)));dialog.querySelectorAll('[data-account-options]').forEach(b=>b.onclick=()=>{const row=b.closest('.managed-account'),existing=row.querySelector('.account-options-menu');dialog.querySelectorAll('.account-options-menu').forEach(x=>x.remove());if(existing)return;const menu=document.createElement('div');menu.className='account-options-menu';menu.setAttribute('role','menu');menu.innerHTML='<button role="menuitem">Log Out</button>';row.append(menu);menu.querySelector('button').onclick=()=>act(async()=>{const uid=b.dataset.accountOptions;if(uid===S.user.uid){await engine?.leave();await api('/session',{method:'DELETE'});await forgetAccount(uid);await signOut(auth)}else{await forgetAccount(uid);dialog.close();manageAccounts()}});menu.querySelector('button').focus();});dialog.querySelector('[data-add-account]').onclick=()=>{dialog.close();addAccountDialog()};}
function addAccountDialog(){const dialog=modal('Add an account',`<form id="add-account-form"><label>USERNAME OR EMAIL<input name="handle" autocomplete="username" required></label><label>PASSWORD<input name="password" type="password" autocomplete="current-password" required></label><p class="form-error" role="alert"></p><button class="primary wide" type="submit">Log In</button></form>`);const form=dialog.querySelector('form');form.onsubmit=async ev=>{ev.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const uid=await addAccount(form.elements.handle.value.trim(),form.elements.password.value);dialog.close();await activateAccount(uid)}catch(error){form.querySelector('.form-error').textContent=error.code==='auth/invalid-credential'?'Incorrect username or password.':error.message;submit.disabled=false}};form.elements.handle.focus();}
function profile(uid){if(uid!==S.user.uid)return profiles.full(uid);const p=user(uid),self=uid===S.user.uid;const dialog=modal(self?'Your account':p.name,`<div class="profile-banner"></div><div class="profile-details">${avatar({...p,status:self?p.status:p.presence||p.status},'large')}<h1>${e(p.name)}</h1><p>@${e(p.handle)}</p>${self?`<label>DISPLAY NAME<input id="profile-name" maxlength="48" value="${e(p.name)}"></label><label>USERNAME<input id="profile-handle" maxlength="20" value="${e(p.handle)}"></label><label>PRONOUNS<input id="profile-pronouns" maxlength="40"></label><label>BIO<textarea id="profile-bio" maxlength="190"></textarea></label><label>BANNER COLOR<input id="profile-banner" type="color" value="#232428"></label><label>PROFILE PHOTO<input type="file" id="avatar-input" accept="image/png,image/jpeg,image/webp"></label><button type="button" class="secondary" id="adjust-avatar" ${p.avatar?'':'hidden'}>Adjust Image</button><p class="muted">JPG, PNG or WebP. Drag and zoom to position your photo.</p><button class="primary wide" id="save-profile">Save Changes</button>`:`<button class="primary wide" id="profile-message">Message</button>`}</div>`);if(!self){dialog.querySelector('#profile-message').onclick=()=>{dialog.close();act(()=>chatWith(uid));};return;}dialog.querySelector('#save-profile').disabled=true;for(const id of ['profile-bio','profile-pronouns','profile-banner'])dialog.querySelector('#'+id).disabled=true;profiles.get(uid).then(extra=>{if(!dialog.isConnected)return;dialog.querySelector('#profile-bio').value=extra.bio;dialog.querySelector('#profile-pronouns').value=extra.pronouns;dialog.querySelector('#profile-banner').value=extra.banner;dialog.querySelector('.profile-banner').style.background=extra.banner;dialog.querySelector('#save-profile').disabled=false;for(const id of ['profile-bio','profile-pronouns','profile-banner'])dialog.querySelector('#'+id).disabled=false;}).catch(error=>toast(error.message));dialog.querySelector('#profile-banner').oninput=ev=>dialog.querySelector('.profile-banner').style.background=ev.target.value;let changedAvatar,avatarSource=p.avatar;const previewAvatar=async source=>{try{const result=await editAvatar({source,modal});if(result){avatarSource=source;changedAvatar=result;dialog.querySelector('.profile-details>.avatar').innerHTML=`<img src="${result}" alt="Profile preview">`;dialog.querySelector('#adjust-avatar').hidden=false;}}catch(error){toast(error.message)}};dialog.querySelector('#adjust-avatar').onclick=()=>previewAvatar(avatarSource);dialog.querySelector('#avatar-input').onchange=async event=>{const f=event.target.files[0];if(!f)return;if(f.size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('Use a JPG, PNG or WebP under 10 MB.');return}const reader=new FileReader();reader.onload=async()=>{await previewAvatar(reader.result);event.target.value=''};reader.readAsDataURL(f);};dialog.querySelector('#save-profile').onclick=()=>act(async()=>{S.user=(await api('/me',{method:'PUT',body:{name:dialog.querySelector('#profile-name').value,handle:dialog.querySelector('#profile-handle').value,status:S.user.status,...(changedAvatar?{avatar:changedAvatar}:{})}})).user;await api('/profiles/'+encodeURIComponent(S.user.uid),{method:'PUT',body:{bio:dialog.querySelector('#profile-bio').value,pronouns:dialog.querySelector('#profile-pronouns').value,banner:dialog.querySelector('#profile-banner').value}});dialog.close();await refresh();toast('Account updated.');});}
function friendMenu(uid,anchor){const f=user(uid),rel=S.friends.find(x=>x.uid===uid);popup(anchor,[{id:'message',icon:'chat',label:'Message',run:()=>chatWith(uid)},{id:'voice',icon:'phone',label:'Start Voice Call',run:async()=>{await chatWith(uid);await startCall('voice');}},{id:'video',icon:'video',label:'Start Video Call',run:async()=>{await chatWith(uid);await startCall('video');}},'-',{id:'block',icon:'shield',label:S.blocks.some(x=>x.target===uid)?'Unblock':'Block',danger:true,run:async()=>{await api('/blocks',{method:'POST',body:{target:uid,blocked:!S.blocks.some(x=>x.target===uid)}});await refresh();}},{id:'remove',icon:'trash',label:'Remove Friend',danger:true,run:()=>confirmAction('Remove '+f.name+'?','You can add them again by username.',async()=>{await api('/friends/'+encodeURIComponent(rel.id),{method:'PATCH',body:{action:'remove'}});await refresh();})}]);}
function confirmAction(title,description,fn){const dialog=modal(title,`<p>${e(description)}</p><footer><button class="text-button" data-no>Cancel</button><button class="danger-button" data-yes>Confirm</button></footer>`);dialog.querySelector('[data-no]').onclick=()=>dialog.close();dialog.querySelector('[data-yes]').onclick=()=>act(async()=>{await fn();dialog.close();});}
