if(import.meta.env.DEV)window.__pixl={get state(){return S},get call(){return engine},api};

if('serviceWorker'in navigator&&!import.meta.env.DEV)window.addEventListener('load',()=>navigator.serviceWorker.register(new URL('sw.js',document.baseURI)).catch(()=>{}));

document.addEventListener('error',event=>{const image=event.target;if(image instanceof HTMLImageElement&&image.classList.contains('emoji'))image.replaceWith(document.createTextNode(image.alt));},true);

document.addEventListener('click',event=>{const button=event.target.closest('[data-bot-play]');if(button)act(async()=>{button.disabled=true;try{await movies.play(button.dataset.botPlay);}finally{button.disabled=false;}});});
document.addEventListener('input',event=>{if(!event.target.matches('[data-bot-filter]'))return;const card=event.target.closest('[data-bot-library]'),words=event.target.value.trim().toLowerCase().split(/\s+/).filter(Boolean);let count=0;for(const video of card.querySelectorAll('[data-bot-search]')){video.hidden=!words.every(word=>video.dataset.botSearch.includes(word));if(!video.hidden)count++;}card.querySelector('.bot-no-results').hidden=count>0;});

applyTheme(localStorage.getItem('vela.theme'));

const profileExtras=createProfileExtras({api,modal,toast,self:()=>S.user,showTitle:async key=>{S.view='movies';render();await movies.show(key)}});
const connections=createConnections({S,api,modal,toast,render,renderMessages,renderUpload,openChat,user,title,active,popup,updateMessage,getEngine:()=>engine,hydrateFiles,attachment,settings,messageMenu,refresh,connectLive,profileExtras:uid=>profileExtras.show(uid),retry:async()=>{for(const m of S.outbox)m.failed=false;await flushOutbox()},sendFile:async(file,cid)=>{const uid=S.user.uid,{upload}=await connections.queue.add(file,cid);if(S.user?.uid!==uid)throw Error('Your account changed.');const message={id:crypto.randomUUID(),conversation:cid,sender:uid,text:'',upload:upload.id,attachment:upload,created:Date.now(),pending:true};S.outbox.push(message);persistOutbox();renderMessages();await flushOutbox()}});

window.addEventListener('vela-profile-extras',ev=>act(()=>profileExtras.show(ev.detail)));

window.addEventListener('vela-open-connections',()=>settings('connections'));
